// Get input from AI agent
const input = $input.item.json;

// Helper to extract data from various possible formats
function extract(obj, keys) {
  for (const key of keys) {
    if (obj[key]) {
      const val = obj[key];
      // Handle if value is an object with 'value' property
      if (typeof val === 'object' && val.value) return String(val.value).trim();
      // Handle direct string
      if (typeof val === 'string') return val.trim();
    }
  }
  return '';
}

// Extract all fields
const fullName = extract(input, ['Full_Name', 'Full Name', 'fullName', 'name']);
const email = extract(input, ['Email_Address', 'Email Address', 'email']);
const phone = extract(input, ['Phone_Number', 'Phone Number', 'phone']);
const company = extract(input, ['Company_Name', 'Company Name', 'company']);
const address = extract(input, ['Address', 'address']);
const summary = extract(input, ['Client_Summary__AI_', 'Client Summary (AI)', 'summary']);
const clientType = extract(input, ['Client_Type', 'Client Type (AI)', 'clientType']);

// Validation
if (!fullName) {
  return { json: { error: 'Full Name is required', success: false } };
}
if (!email) {
  return { json: { error: 'Email Address is required', success: false } };
}

// Validate email format
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(email)) {
  return { json: { error: `Invalid email format: ${email}`, success: false } };
}

// Prepare Airtable API payload
return {
  json: {
    fields: {
      'Full Name': fullName,
      'Email Address': email.toLowerCase(),
      'Phone Number': phone,
      'Company Name': company,
      'Address': address,
      'Client Summary (AI)': summary,
      'Client Type (AI)': clientType
    }
  }
};
